def run(tasks, retries=2):
    for name, fn in tasks:
        for attempt in range(1, retries + 2):
            try:
                print(name, '->', fn())
                break
            except ConnectionError as e:
                print(name, f'attempt {attempt} failed: {e}')
                if attempt == retries + 1:
                    raise

