from datetime import datetime
counts = {}
errors = {}
for line in open('app.log'):
    parts = line.rstrip('\n').split(' ', 3)
    try:
        datetime.strptime(parts[0] + ' ' + parts[1], '%Y-%m-%d %H:%M')
    except (ValueError, IndexError):
        counts['MALFORMED'] = counts.get('MALFORMED', 0) + 1
        continue
    level = parts[2]
    counts[level] = counts.get(level, 0) + 1
    if level == 'ERROR':
        errors[parts[3]] = errors.get(parts[3], 0) + 1
print(counts)
