class Emitter:
    def __init__(self):
        self.handlers = {}
    def on(self, event, callback):
        self.handlers.setdefault(event, []).append(callback)
    def emit(self, event, data):
        for cb in self.handlers.get(event, []):
            cb(data)

em = Emitter()
em.on('save', lambda d: print(f'logger: saved {d}'))
em.on('save', lambda d: print(f'audit: saved {d}'))
em.emit('save', 'report.txt')

def counted(fn):
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return fn(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@counted
def greet(name):
    return f'hello {name}'

